-- Queer Atlas: four queer-welcoming hotels each in Brno, Granada, Aarhus and Valparaiso.
-- Researched 2026-08-27. Idempotent; aliases prevent duplicate inserts.
-- All types and vibe tags are valid under the current public.places constraints.

begin;

alter table if exists public.places
  add column if not exists venue_intel jsonb not null default '{}'::jsonb;

with raw_hotels as (
  select * from jsonb_to_recordset($qa_hotels$
[
 {"name":"Grandhotel Brno","aliases":"Grandhotel Brno|Grand Hotel Brno","city":"brno","description":"A historic 105-room city hotel opposite Brno's main station, combining a formal central-European exterior with contemporary rooms, a lobby bar and Garden Restaurant. Its location favours train arrivals and quick movement into the old centre rather than a secluded resort stay.","vibe":"historic station-side city hotel with formal architecture and practical central access","tags":"luxury,cultural,mixed","hours":"Reception operates 24 hours; restaurant, breakfast, fitness and other facilities follow their own current schedules.","link":"https://grandhotelbrno.cz/en/","location":"Benešova 605/18, 602 00 Brno, Czech Republic","lat":49.192624,"lng":16.613000,"arrival":"Station traffic and tour arrivals can make the forecourt and reception busy around standard check-in; confirm parking access before entering the centre.","best":"Best for railway convenience, a traditional full-service stay and walking access to both the old town and evening venues.","crowd":"Queer couples and solo travellers mix with rail passengers, business guests, tour groups and cultural visitors in a mainstream city hotel.","dress":"Everyday city clothing is appropriate; the restaurant and formal public rooms suit neat smart-casual dress without a published restrictive code.","inclusion":"TravelGay marks the property approved and states that LGBTQ+ guests are accepted in a warm, welcoming environment.","basis":"Current TravelGay approval paired with the hotel's official contact, room and service information.","class":"Historic four-star city hotel","coords":"Mapbox Geocoding v6 exact-address result for Benešova 605/18, checked 2026-08-27.","sources":["https://www.travelgay.com/gay-brno","https://grandhotelbrno.cz/en/contact/"]},
 {"name":"Hotel International Brno","aliases":"Hotel International Brno|Best Western Premier Hotel International|Best Western Premier Hotel International Brno","city":"brno","description":"A large modernist landmark beneath Špilberk Castle with central parking, restaurants, bars and wellness facilities. It sits on Husova close to But Bar and the historic core, making it the strongest option here for travellers wanting full hotel infrastructure without leaving the queer social circuit.","vibe":"modernist central landmark with castle views, full service and immediate nightlife access","tags":"luxury,cultural,social","hours":"Reception operates 24 hours; restaurants, pool, wellness and parking use current hotel schedules and availability.","link":"https://www.hotelinternational.cz/en/","location":"Husova 200/16, 602 00 Brno, Czech Republic","lat":49.195004,"lng":16.605515,"arrival":"Conference groups and city events can pressure the garage and lobby; reserve parking and an adapted room directly rather than relying on a booking note.","best":"Best for central comfort, castle views and the shortest walk of this group to But Bar, Pride venues and Brno's principal sights.","crowd":"LGBTQ+ leisure guests share the large property with conferences, business travellers, couples and Central European city-break groups.","dress":"City casual works throughout the day; restaurants and event spaces become smart-casual while the wellness area has separate attire rules.","inclusion":"TravelGay describes it as LGBT-friendly and approved, with LGBTQ+ guests accepted and dedicated personal service.","basis":"Current specialist LGBTQ+ approval plus the hotel's official location and active-service documentation.","class":"Large upscale modernist city hotel","coords":"Mapbox Geocoding v6 exact-address result for Husova 200/16, checked 2026-08-27.","sources":["https://www.travelgay.com/gay-brno","https://www.hotelinternational.cz/en/contacts/"]},
 {"name":"Grandezza Hotel Luxury Palace","aliases":"Grandezza Hotel Luxury Palace|Hotel Grandezza|Grandezza Hotel","city":"brno","description":"A five-star boutique hotel overlooking Zelný trh, with a hand-painted glass lobby ceiling, individually styled rooms and direct views toward Petrov and Špilberk. It places guests inside the Pride Park setting and suits a polished stay where historic-square atmosphere matters more than spa-resort scale.","vibe":"ornate market-square boutique luxury with landmark views and immediate cultural energy","tags":"luxury,cultural,cozy","hours":"Reception and guest service operate daily; breakfast, restaurant, massages and other facilities require current schedules or reservations.","link":"https://www.grandezzahotel.com/en/about-us/","location":"Zelný trh 314/2, 602 00 Brno, Czech Republic","lat":49.192475,"lng":16.609687,"arrival":"Vehicle access around the historic market is limited and event days alter loading conditions; arrange parking and luggage handling with reception.","best":"Best for couples prioritising old-town views, Pride Park proximity and a smaller luxury property with a strong sense of place.","crowd":"Queer couples, leisure travellers, special-occasion guests and cultural visitors share an intimate mainstream boutique environment.","dress":"Polished city wear fits the ornate lobby and restaurant, although there is no published appearance gate for hotel guests.","inclusion":"TravelGay actively approves the hotel and identifies LGBTQ-friendly management, accepted community guests and welcoming service.","basis":"Current TravelGay approval matched to the active first-party hotel, room and address record.","class":"Five-star historic boutique hotel","coords":"Mapbox Geocoding v6 exact-address result for Zelný trh 314/2, checked 2026-08-27.","sources":["https://www.travelgay.com/gay-brno","https://www.grandezzahotel.com/en/about-us/"]},
 {"name":"VV Hotel & Apartments","aliases":"VV Hotel & Apartments|VV Hotel|VV Hotel B & B|VV Hotel Garni","city":"brno","description":"A compact central hotel and apartment property near Vaňkovka and the main station, offering modern non-smoking rooms, breakfast and free on-site parking. It trades grand public rooms for practical space and straightforward access, including apartment formats useful for longer queer city stays.","vibe":"quiet modern hotel-apartment base balancing value, parking and central railway access","tags":"cozy,relax,mixed","hours":"Reception and arrival follow the hotel's current booking instructions; published check-in begins at 15:00 and should be reconfirmed.","link":"https://www.vvhotel.cz/en/","location":"Mlýnská 495/8a, 602 00 Brno, Czech Republic","lat":49.190834,"lng":16.615935,"arrival":"The small property and private parking require accurate arrival instructions; confirm late check-in and apartment access directly before travel.","best":"Best for value-conscious couples, drivers and longer stays needing more room while remaining close to the station and old centre.","crowd":"Queer travellers mix with couples, families, rail users and guests using apartment-style accommodation in a low-key mainstream property.","dress":"There is no hotel dress code; comfortable city clothing fits the breakfast room and practical apartment setting.","inclusion":"TravelGay lists VV as approved and states that LGBTQ+ community members are accepted by LGBTQ-friendly management.","basis":"Current specialist approval combined with the hotel's official contact, facilities and exact registered address.","class":"Independent hotel and serviced apartments","coords":"Exact address cross-checked against official contact data and published GPS 49.190834,16.615935 after Mapbox matched the wrong Mlýnská.","sources":["https://www.travelgay.com/gay-brno","https://www.vvhotel.cz/en/contact/"]},

 {"name":"Room Mate Leo","aliases":"Room Mate Leo|Room Mate Leo Granada|Room Mate Leo, Granada","city":"granada","description":"A colourful design hotel on pedestrian Campo Verde with a year-round heated rooftop pool, Alhambra views and breakfast served until noon. Its location keeps the cathedral, Puerta Real and Granada's queer bar cluster within an easy walk, while the small rooftop gives it a more social identity than a conventional city room.","vibe":"colourful central design hotel with a heated rooftop pool and late-breakfast rhythm","tags":"social,cultural,relax","hours":"Reception operates 24 hours; breakfast is published until 12:00 and rooftop access follows weather and guest rules.","link":"https://room-matehotels.com/gb/hotel-leo-granada/","location":"Calle Campo Verde 1, 18001 Granada, Spain","lat":37.173842,"lng":-3.600383,"arrival":"The pedestrian-centre location complicates vehicle access; ask reception for the current permitted route and parking arrangement before arrival.","best":"Best for travellers wanting design, rooftop downtime and a short walk to both monuments and the Santa Paula queer nightlife cluster.","crowd":"Queer couples and friends mix with international city-break visitors, design travellers and pet owners in a lively mainstream boutique hotel.","dress":"Colourful casual city wear fits the brand; use normal pool attire on the roof and smart-casual clothing for evening public spaces.","inclusion":"Current LGBTQ travel sources identify Room Mate Leo as gay-friendly, while the property is also listed in Hotels.com's LGBTQIA-welcoming collection.","basis":"Specialist queer-travel classification and Hotels.com inclusion paired with Room Mate's current first-party property details.","class":"Four-star lifestyle boutique hotel","coords":"Mapbox Geocoding v6 exact-address result for Campo Verde 1, checked 2026-08-27.","sources":["https://www.gayout.com/europe/spain/granada","https://room-matehotels.com/gb/hotel-leo-granada/","https://www.hotels.com/tgp/lodging/theme/lgbtfriendly/553248635976005992/vega-de-granada"]},
 {"name":"Barceló Carmen Granada","aliases":"Barceló Carmen Granada|Barcelo Carmen Granada|Barceló Carmen Granada Hotel","city":"granada","description":"A 251-room central hotel with contemporary Alhambra-inspired interiors, a panoramic rooftop pool, mountain views, gym and two food-and-drink concepts. It gives queer visitors full-service scale and a visible rooftop while remaining close to Puerta Real and the walkable night circuit.","vibe":"large contemporary city hotel with panoramic rooftop energy and Alhambra-inspired design","tags":"luxury,social,cultural","hours":"Reception operates 24 hours; check-in begins at 14:00, while rooftop, pool, gym and restaurants follow separate schedules.","link":"https://www.barcelo.com/en-gb/barcelo-carmen-granada/","location":"Acera del Darro 62, 18005 Granada, Spain","lat":37.170537,"lng":-3.598264,"arrival":"The busy central avenue and 251-room scale create check-in and lift peaks; reserve parking and accessible rooms directly in advance.","best":"Best for travellers who want rooftop views, broader facilities and central shopping access rather than a tiny historic-house hotel.","crowd":"LGBTQ+ leisure guests share the property with tour groups, families, business travellers and rooftop restaurant visitors.","dress":"Relaxed city wear works by day; B-Heaven rooftop and dinner spaces lean smart-casual without a queer-specific appearance code.","inclusion":"The hotel appears in Hotels.com's current LGBTQIA-welcoming Granada selection and Expedia explicitly states acceptance of every orientation and gender identity.","basis":"Two current inclusion-labelled travel records plus Barceló's official active property and accessibility information.","class":"Large four-star full-service hotel","coords":"Mapbox Geocoding v6 exact-address result for Acera del Darro 62, checked 2026-08-27.","sources":["https://www.hotels.com/tgp/lodging/theme/lgbtfriendly/553248635976005992/vega-de-granada","https://www.barcelo.com/en-gb/barcelo-carmen-granada/"]},
 {"name":"Hotel Alhambra Palace","aliases":"Hotel Alhambra Palace|Alhambra Palace Hotel","city":"granada","description":"A landmark luxury hotel opened in 1910 above the city beside the Alhambra, known for ornate neo-Nasrid interiors, panoramic terraces and formal hospitality. Its hilltop setting delivers romance and views but requires more deliberate transport to the central queer bars after midnight.","vibe":"grand hilltop heritage luxury with theatrical interiors and wide Granada views","tags":"luxury,cultural,cozy","hours":"Reception operates 24 hours; restaurant, terrace, parking collection and other guest services follow current hotel schedules.","link":"https://www.hotelalhambrapalace.com/en/","location":"Plaza Arquitecto García de Paredes 1, 18009 Granada, Spain","lat":37.174078,"lng":-3.590010,"arrival":"The steep approach, limited nearby parking and monument traffic make the hotel's collection service or a taxi preferable with luggage.","best":"Best for couples seeking heritage atmosphere, Alhambra proximity and panoramic evenings rather than immediate bar-hopping access.","crowd":"Queer couples and special-occasion travellers mix with heritage tourists, luxury groups and restaurant guests in a formal mainstream setting.","dress":"Smart-casual clothing suits the historic lounges and terrace dining; ordinary guest access is not governed by a published restrictive dress code.","inclusion":"Hotels.com includes the property in its current LGBTQIA-welcoming Granada catalogue, supporting a careful queer-friendly rather than queer-owned claim.","basis":"Current LGBTQIA-welcoming classification paired with direct official evidence for operation, address and guest logistics.","class":"Five-star landmark heritage hotel","coords":"Mapbox Geocoding v6 exact-address result for Plaza Arquitecto García de Paredes 1, checked 2026-08-27.","sources":["https://www.hotels.com/tgp/lodging/theme/lgbtfriendly/553248635976005992/vega-de-granada","https://www.hotelalhambrapalace.com/en/contact-and-location"]},
 {"name":"Hotel Anacapri","aliases":"Hotel Anacapri|Anacapri Granada","city":"granada","description":"A 49-room hotel inside a restored eighteenth-century house near Plaza Nueva, with an Andalusian patio, reading room and simple breakfast café. The intimate scale and central location suit guests who prioritise character and walking access over rooftop spectacle or resort facilities.","vibe":"intimate restored-house hotel with an Andalusian patio and highly walkable old-town position","tags":"cozy,cultural,relax","hours":"Reception operates daily; breakfast is 07:30-10:30 and the guest bar is published from 08:00-23:00.","link":"https://hotelanacapri.com/","location":"Calle Joaquín Costa 7, 18010 Granada, Spain","lat":37.176545,"lng":-3.597345,"arrival":"Restricted central streets and a rising bollard require the hotel's exact driving instructions; unload only at the designated short-stay point.","best":"Best for walkers wanting an affordable character hotel between Plaza Nueva, the cathedral and Granada's compact queer circuit.","crowd":"Queer couples and solo travellers mix with cultural visitors, families and independent sightseers in a quiet small-hotel environment.","dress":"Casual sightseeing clothes fit the patio and café; there is no published dress requirement beyond ordinary shared-space etiquette.","inclusion":"Hotel Anacapri appears in Hotels.com's current LGBTQIA-welcoming Granada collection; no ownership or specialist certification is implied.","basis":"Current inclusion-labelled directory evidence combined with the hotel's detailed official access, service and address information.","class":"Three-star historic-house hotel","coords":"Mapbox Geocoding v6 exact-address result for Joaquín Costa 7, checked 2026-08-27.","sources":["https://www.hotels.com/tgp/lodging/theme/lgbtfriendly/553248635976005992/vega-de-granada","https://hotelanacapri.com/contacto/"]},

 {"name":"Scandic Aarhus City","aliases":"Scandic Aarhus City|Scandic Aarhus City Hotel","city":"aarhus","description":"A modern central Scandic with Scandinavian rooms, restaurant, bar, bicycles and views toward ARoS and the harbour. Its Østergade address places GBAR and the central pedestrian streets close by, making it the clearest nightlife-oriented hotel in this Aarhus group.","vibe":"modern Scandinavian city hotel with bar energy and immediate access to central queer nightlife","tags":"social,cultural,mixed","hours":"Reception and guest service operate daily; restaurant, bar, bicycle and parking services follow current hotel schedules.","link":"https://www.scandichotels.com/en/hotels/scandic-aarhus-city","location":"Østergade 10, 8000 Aarhus C, Denmark","lat":56.154252,"lng":10.205505,"arrival":"Central parking and weekend shopping traffic can slow arrival; confirm charging, garage access and an adapted room before travel.","best":"Best for direct walking access to GBAR, shopping, Dokk1 and the compact centre while retaining a full-service chain hotel.","crowd":"LGBTQ+ weekend guests mix with business travellers, families, restaurant visitors and Scandinavian city-break groups.","dress":"Relaxed Nordic city clothing fits the lobby and bar; restaurant evenings remain informal smart-casual with no published restrictive code.","inclusion":"TravelGay actively approves the hotel, citing LGBTQ-friendly management, accepted LGBTQ+ guests and a seamless welcoming experience.","basis":"Current specialist approval reinforced by the Hotels.com LGBTQIA-welcoming list and Scandic's official hotel record.","class":"Four-star modern city hotel","coords":"Mapbox Geocoding v6 exact-address result for Østergade 10, checked 2026-08-27.","sources":["https://www.travelgay.com/hotels/scandic-aarhus-city","https://www.scandichotels.com/en/hotels/scandic-aarhus-city","https://www.hotels.com/de1644827-th21/lgbtq-welcoming-hotels-aarhus-denmark/"]},
 {"name":"SOFS Boutique Hotel","aliases":"SOFS Boutique Hotel|Sofs Boutique Hotel","city":"aarhus","description":"A 26-room Art Deco-inspired boutique hotel in the Latin Quarter with individually decorated rooms, an organic breakfast café and a plant-filled courtyard used year-round. Its neighbourhood scale offers a calmer, more personal alternative to the station-area hotels while staying near Café Sappho and central culture.","vibe":"small Art Deco-inspired Latin Quarter hotel with organic breakfast and a leafy courtyard","tags":"cozy,cultural,relax","hours":"Reception and check-in follow the property's current instructions; breakfast café and courtyard service have separate hours.","link":"https://sofshotel.dk/en/","location":"Guldsmedgade 40, 8000 Aarhus C, Denmark","lat":56.160025,"lng":10.207916,"arrival":"The historic-quarter setting and annex rooms make access details important; request the correct room location for stairs, luggage or mobility needs.","best":"Best for couples and solo travellers wanting local design, quiet courtyard time and walking access to Sappho and the Latin Quarter.","crowd":"Queer city-break guests mix with design-conscious couples, cultural travellers and café visitors in a small mainstream boutique property.","dress":"Come-as-you-are city clothing suits the informal courtyard and organic breakfast room; no appearance policy is published.","inclusion":"Hotels.com lists SOFS within its current LGBTQIA-welcoming Aarhus collection, supporting a welcoming claim without overstating certification.","basis":"Current LGBTQIA-welcoming catalogue placement paired with first-party details on scale, design, rooms and location.","class":"Independent three-star boutique hotel","coords":"Mapbox Geocoding v6 exact-address result for Guldsmedgade 40, checked 2026-08-27.","sources":["https://www.hotels.com/de1644827-th21/lgbtq-welcoming-hotels-aarhus-denmark/","https://sofshotel.dk/en/information/"]},
 {"name":"Comwell Aarhus Dolce by Wyndham","aliases":"Comwell Aarhus Dolce by Wyndham|Comwell Aarhus|Comwell Hotel Aarhus","city":"aarhus","description":"A 240-room design hotel near the station and harbour, created with HAY interiors and offering city views, Restaurant V, terrace bar, coworking and two gyms. It works well for guests who need business-grade facilities or accessible rooms while remaining within a walk of central queer venues.","vibe":"high-rise Danish design hotel with harbour views, coworking and polished full-service scale","tags":"luxury,cultural,social","hours":"Reception operates 24 hours; check-in begins at 15:00 and restaurant, bar, lounge and gyms use current schedules.","link":"https://www.comwell.com/en/hotels/comwell-hotel-aarhus","location":"Værkmestergade 2, 8000 Aarhus C, Denmark","lat":56.150284,"lng":10.209292,"arrival":"The large hotel and station district produce conference and parking peaks; reserve underground parking and specific accessible features in advance.","best":"Best for queer business travellers, longer stays and couples wanting modern design, city views and full facilities near transport.","crowd":"LGBTQ+ guests mix with conferences, corporate travellers, couples and international groups in a busy mainstream design hotel.","dress":"Modern city casual works in public areas; Restaurant V and event spaces become polished smart-casual without a queer-specific rule.","inclusion":"Hotels.com places Comwell Aarhus in its current LGBTQIA-welcoming hotel collection for Aarhus.","basis":"Current inclusion-labelled catalogue record plus direct official evidence for active operation, accessibility and exact address.","class":"Four-star design and conference hotel","coords":"Mapbox Geocoding v6 exact-address result for Værkmestergade 2, checked 2026-08-27.","sources":["https://www.hotels.com/de1644827-th21/lgbtq-welcoming-hotels-aarhus-denmark/","https://www.comwell.com/en/hotels/comwell-hotel-aarhus","https://www.comwell.com/en/hotels/comwell-hotel-aarhus/contact"]},
 {"name":"Scandic The Mayor","aliases":"Scandic The Mayor|The Mayor Hotel Aarhus","city":"aarhus","description":"A cosy station-square Scandic beside Aarhus H, Musikhuset and ARoS, with a bar, always-open gym and compact room categories. It prioritises rail convenience and cultural access over resort facilities, while the direct walk through the centre keeps GBAR and Pride activity reachable.","vibe":"cosy station-square hotel connecting rail convenience, culture and central nightlife","tags":"cozy,cultural,mixed","hours":"Reception operates daily; breakfast, bar, parking and the always-open gym follow current official details.","link":"https://www.scandichotels.com/en/hotels/scandic-the-mayor","location":"Banegårdspladsen 14, 8000 Aarhus C, Denmark","lat":56.151018,"lng":10.202749,"arrival":"Renovation is currently documented through October 2026, with weekday noise possible; confirm room position before booking a daytime rest stay.","best":"Best for train travellers, concerts and ARoS visits who want a simple central base rather than the public buzz of a larger design hotel.","crowd":"Queer couples and solo visitors mix with rail travellers, culture audiences, business guests and short-break visitors.","dress":"Everyday Nordic city clothing fits the relaxed hotel and bar; no formal or queer-specific appearance requirement is published.","inclusion":"Hotels.com includes Scandic The Mayor in its current Aarhus LGBTQIA-welcoming hotel selection.","basis":"Current inclusion-list evidence matched to Scandic's live property, renovation, access and service information.","class":"Central Scandic city hotel","coords":"Mapbox Geocoding v6 exact-address result for Banegårdspladsen 14, checked 2026-08-27.","sources":["https://www.hotels.com/de1644827-th21/lgbtq-welcoming-hotels-aarhus-denmark/","https://www.scandichotels.com/en/hotels/scandic-the-mayor"]},

 {"name":"WineBox Valparaíso","aliases":"WineBox Valparaíso|Winebox Valparaiso|Hotel Winebox Valparaiso","city":"valparaiso","description":"A highly individual hotel assembled from repurposed shipping containers, with ocean views from every room, private kitchenettes, artist murals and a rooftop devoted to breakfast, local wine and sunset. The steep Baquedano setting turns arrival into part of the Valparaíso experience rather than a conventional flat-city check-in.","vibe":"colour-saturated container hotel joining street art, local wine and panoramic port sunsets","tags":"cultural,social,cozy","hours":"Guest reception follows current booking instructions; rooftop breakfast, tastings, tours and private events use separate schedules.","link":"https://hotelwineboxvalparaiso.com/","location":"Avenida Baquedano 763, Valparaíso, Chile","lat":-33.050786,"lng":-71.618474,"arrival":"The hillside street and unconventional building require confirmed transport, luggage and accessibility arrangements; do not assume a flat step-free route.","best":"Best for queer couples and creative travellers wanting local art, wine and views rather than uniform chain-hotel service.","crowd":"LGBTQ+ guests mix with wine travellers, artists, international couples and rooftop event participants in a social independent property.","dress":"Colourful casual clothing fits the art-led rooms and rooftop; weather layers and secure hillside footwear are more important than formality.","inclusion":"Hotels.com lists WineBox among Valparaíso's current LGBTQIA-welcoming hotels; the claim is welcoming, not queer ownership.","basis":"Current LGBTQIA-welcoming catalogue placement paired with the hotel's official room, rooftop, art and address information.","class":"Independent three-star design hotel","coords":"Mapbox Geocoding v6 exact-address result for Avenida Baquedano 763, checked 2026-08-27.","sources":["https://www.hotels.com/tgp/lodging/theme/lgbtfriendly/553248635997965347/valparaiso","https://hotelwineboxvalparaiso.com/"]},
 {"name":"Fauna Hotel Valparaíso","aliases":"Fauna Hotel Valparaíso|Fauna Hotel Valparaiso|Fauna Hotel","city":"valparaiso","description":"A restored 1870 hillside building on Pasaje Dimalow with rooms shaped by Chilean artists, native wood and raw-earth materials, plus a panoramic restaurant and wellness experiences. The public terrace gives it social energy, while the historic structure and steep approach require realistic mobility planning.","vibe":"artist-made Cerro Alegre hotel with raw materials, wellness and a panoramic restaurant terrace","tags":"cultural,social,relax","hours":"Reception operates 24 hours; the restaurant publishes daily service around 12:30-22:00 and experiences require reservations.","link":"https://faunahotel.com/valparaiso/","location":"Pasaje Dimalow 166, Cerro Alegre, Valparaíso, Chile","lat":-33.043737,"lng":-71.627112,"arrival":"Pasaje Dimalow is reached through steep heritage terrain and lift conditions vary; discuss luggage, parking and accessible movement before arrival.","best":"Best for couples who want Cerro Alegre's restaurant and arts life directly outside the room, with evening views on site.","crowd":"Queer travellers mix with artists, international couples, restaurant visitors and wellness guests in a bohemian mainstream hotel.","dress":"Layered port-city casual fits the hotel; restaurant evenings lean neat casual and walking shoes are essential on the surrounding hills.","inclusion":"Hotels.com includes Fauna Hotel in its current LGBTQIA-welcoming Valparaíso collection.","basis":"Current inclusion-labelled listing plus first-party evidence for active hotel operation, services and location.","class":"Independent three-star heritage design hotel","coords":"Mapbox Geocoding v6 exact-address result for Pasaje Dimalow 166, checked 2026-08-27.","sources":["https://www.hotels.com/tgp/lodging/theme/lgbtfriendly/553248635997965347/valparaiso","https://faunahotel.com/valparaiso/"]},
 {"name":"Hotel Boutique 17","aliases":"Hotel Boutique 17|Boutique 17|Hotel 17","city":"valparaiso","description":"A compact contemporary hotel on Cerro Concepción with bay-facing rooms, private balconies in selected categories, bar, restaurant and 24-hour reception. It offers easier access to the UNESCO hill's galleries and nightlife than a distant chain, while room-by-room views and terrace access should be confirmed before booking.","vibe":"small contemporary Cerro Concepción hotel focused on bay views, balconies and attentive local guidance","tags":"cozy,cultural,relax","hours":"Reception operates 24 hours; breakfast, restaurant, bar, transfers and room service follow current schedules.","link":"https://hotel17.cl/en/home/","location":"Papudo 557, Cerro Concepción, Valparaíso, Chile","lat":-33.041911,"lng":-71.626385,"arrival":"Papudo's hill streets and heritage geometry require a planned taxi drop and confirmation of stairs or lift access for the selected room.","best":"Best for queer couples wanting a small hotel inside Cerro Concepción with sea views and restaurants within a short hill walk.","crowd":"LGBTQ+ guests share the property with international couples, independent cultural travellers and short-stay port visitors.","dress":"Relaxed but neat city clothing fits the small bar and restaurant; strong shoes are needed outside on cobbles and slopes.","inclusion":"Hotels.com identifies Hotel Boutique 17 in its current LGBTQIA-welcoming Valparaíso hotel collection.","basis":"Current LGBTQIA-welcoming catalogue evidence combined with the hotel's official address and active guest offer.","class":"Three-star contemporary boutique hotel","coords":"Mapbox Geocoding v6 exact-address result for Papudo 557, checked 2026-08-27.","sources":["https://www.hotels.com/tgp/lodging/theme/lgbtfriendly/553248635997965347/valparaiso","https://hotel17.cl/en/home/"]},
 {"name":"Casa Higueras","aliases":"Casa Higueras|Hotel Casa Higueras","city":"valparaiso","description":"A refined Cerro Alegre hotel in a converted mansion with bay views, terraces, pool, sauna, hot tub and Maralegre restaurant. Its quiet, private atmosphere suits celebratory queer couples, while seasonal Tuesday-Wednesday closure and the hillside layout must be checked before committing to dates.","vibe":"nostalgic-chic mansion retreat with bay terraces, pool calm and intimate dining","tags":"luxury,cozy,relax","hours":"Hotel and restaurant schedules vary seasonally; the official site currently warns of Tuesday-Wednesday low-season closure.","link":"https://casahigueras.cl/esp/hotel/lugar","location":"Calle Higuera 133, Cerro Alegre, Valparaíso, Chile","lat":-33.040683,"lng":-71.630637,"arrival":"The mansion's hillside setting and seasonal operation require advance confirmation of transfer, luggage, room access and restaurant opening.","best":"Best for queer couples prioritising privacy, views, spa-style facilities and an on-site dinner rather than late club proximity.","crowd":"LGBTQ+ couples mix with luxury leisure guests, anniversary travellers, restaurant diners and small private groups.","dress":"Resort-casual clothing fits terraces and pool areas; Maralegre and special evenings suit polished smart-casual dress.","inclusion":"Hotels.com lists Casa Higueras among its current LGBTQIA-welcoming properties in Valparaíso.","basis":"Current LGBTQIA-welcoming catalogue inclusion paired with direct hotel information on location, facilities and seasonal operation.","class":"Four-star mansion boutique hotel","coords":"Mapbox Geocoding v6 exact-address result for Higuera 133, checked 2026-08-27.","sources":["https://www.hotels.com/tgp/lodging/theme/lgbtfriendly/553248635997965347/valparaiso","https://casahigueras.cl/esp/hotel/lugar"]}
]
$qa_hotels$) h(name text,aliases text,city text,description text,vibe text,tags text,hours text,link text,location text,lat double precision,lng double precision,arrival text,best text,crowd text,dress text,inclusion text,basis text,class text,coords text,sources jsonb)
), hotels as (
 select h.*,
   string_to_array(h.tags,',')::text[] as approved_tags,
   jsonb_build_object(
     'queue_wait',arrival,
     'best_nights',best,
     'crowd_mix',crowd,
     'dress_code',dress,
     'staff_inclusivity',inclusion,
     'inclusion_basis',basis,
     'hotel_class',class,
     'coordinate_source',coords,
     'source_urls',sources,
     'research_status','current_lgbtq_welcoming_source_plus_official_hotel_source',
     'updated_at','2026-08-27T00:00:00Z'
   ) as intel
 from raw_hotels h
), updated as (
 update public.places p set
   name=h.name,type='hotel',description=h.description,vibe=h.vibe,
   vibe_tags=h.approved_tags,hours=h.hours,link=h.link,location=h.location,
   lat=h.lat,lng=h.lng,venue_intel=coalesce(p.venue_intel,'{}'::jsonb)||h.intel,
   seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
 from hotels h
 where lower(trim(p.city))=h.city
   and lower(trim(p.name)) in (
     select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name
   )
 returning p.id
)
insert into public.places(
 name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,
 venue_intel,seo_indexable,seo_quality_status,updated_at
)
select h.name,h.city,'hotel',h.description,h.vibe,h.approved_tags,h.hours,h.link,
 h.location,h.lat,h.lng,h.intel,true,'approved',timezone('utc',now())
from hotels h
where not exists (
 select 1 from public.places p
 where lower(trim(p.city))=h.city
   and lower(trim(p.name)) in (
     select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name
   )
);

select public.qa_refresh_city_seo_status(slug)
from (values('brno'),('granada'),('aarhus'),('valparaiso')) v(slug)
where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

-- Human-readable verification: target is four hotels in every city.
select lower(trim(city)) as city,count(*) filter(where type='hotel') as hotel_count,
       count(*) filter(where type='hotel')>=4 as target_met
from public.places
where lower(trim(city)) in('brno','granada','aarhus','valparaiso')
group by lower(trim(city)) order by lower(trim(city));

-- Every batch row must contain exact coordinates, five intelligence fields and sources.
select lower(trim(city)) as city,count(*) as batch_rows,
 count(*) filter(where
   lat between -90 and 90 and lng between -180 and 180
   and char_length(coalesce(venue_intel->>'queue_wait',''))>=24
   and char_length(coalesce(venue_intel->>'best_nights',''))>=24
   and char_length(coalesce(venue_intel->>'crowd_mix',''))>=24
   and char_length(coalesce(venue_intel->>'dress_code',''))>=24
   and char_length(coalesce(venue_intel->>'staff_inclusivity',''))>=24
   and jsonb_array_length(coalesce(venue_intel->'source_urls','[]'::jsonb))>=2
 ) as complete_rows
from public.places
where type='hotel'
 and venue_intel->>'updated_at'='2026-08-27T00:00:00Z'
 and lower(trim(city)) in('brno','granada','aarhus','valparaiso')
group by lower(trim(city)) order by lower(trim(city));

